window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6a5c35fb93aea222"]={"versions": [{"id": "FIG-6a5c35fb93aea222", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines Teilschritts des End-to-End-Schutzprotokolls E2E Profile 4m innerhalb der AUTOSAR E2E-Bibliothek (AUTOSAR_PRS_E2EProtocol). Das Diagramm stellt den internen Ablauf des Einzelschritts „Write DataID“ innerhalb der Schutzfunktion <code>E2E_P04mProtect()</code> dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten und Schnittstellen:</p>\n<ul class=\"fig-list\"><li>Funktionskontext: <code>E2E_P04mProtect()</code>\n</li><li>Konfigurationsstruktur: <code>Config-&gt;DataID</code> (4-Byte-Identifikator)\n</li><li>Zielpuffer: Byte-Array <code>Data[]</code> an den relativen Indizes <code>Offset+4</code> bis <code>Offset+7</code>\n</li><li>Diagrammelemente: Startknoten (Initial Node), eine Aktionsstufe (Action Node) mit der Datenübertragungsoperation sowie ein Endknoten (Activity Final Node). Ein Aufruf-Symbol oben links verweist auf den Kontext <code>E2E_P04mProtect()</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf erfolgt sequenziell:</p>\n<ol class=\"fig-list\"><li>Start am Initial Node.\n</li><li>Ausführung der Aktion: Das 4 Byte große Feld <code>Config-&gt;DataID</code> wird in Big-Endian-Bytereihenfolge in die Bytes <code>Data[Offset+4...Offset+7]</code> geschrieben.\n</li><li>Beendigung am Activity Final Node.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend gemäß Anforderung <code>[PRS_E2E_00761]</code>. Der Schritt stellt sicher, dass die 32-Bit-DataID im Header des serialisierten Payloads an definierter Stelle (<code>Offset + 4</code> bis <code>Offset + 7</code>) in Netzwerk-Byte-Order (Big Endian) abgelegt wird, um Erkennung von Verwechslung und Falschadressierung im Profile 4m zu gewährleisten. Implementierungen müssen exakt diese Byte-Reihenfolge und Adressierung einhalten.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-562203aebc80c395", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines Teilschritts des End-to-End-Schutzprotokolls E2E Profile 4m innerhalb der AUTOSAR E2E-Bibliothek (AUTOSAR_PRS_E2EProtocol). Das Diagramm stellt den internen Ablauf des Einzelschritts „Write DataID“ innerhalb der Schutzfunktion <code>E2E_P04mProtect()</code> dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten und Schnittstellen:</p>\n<ul class=\"fig-list\"><li>Funktionskontext: <code>E2E_P04mProtect()</code>\n</li><li>Konfigurationsstruktur: <code>Config-&gt;DataID</code> (4-Byte-Identifikator)\n</li><li>Zielpuffer: Byte-Array <code>Data[]</code> an den relativen Indizes <code>Offset+4</code> bis <code>Offset+7</code>\n</li><li>Diagrammelemente: Startknoten (Initial Node), eine Aktionsstufe (Action Node) mit der Datenübertragungsoperation sowie ein Endknoten (Activity Final Node). Ein Aufruf-Symbol oben links verweist auf den Kontext <code>E2E_P04mProtect()</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf erfolgt sequenziell:</p>\n<ol class=\"fig-list\"><li>Start am Initial Node.\n</li><li>Ausführung der Aktion: Das 4 Byte große Feld <code>Config-&gt;DataID</code> wird in Big-Endian-Bytereihenfolge in die Bytes <code>Data[Offset+4...Offset+7]</code> geschrieben.\n</li><li>Beendigung am Activity Final Node.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend gemäß Anforderung <code>[PRS_E2E_00761]</code>. Der Schritt stellt sicher, dass die 32-Bit-DataID im Header des serialisierten Payloads an definierter Stelle (<code>Offset + 4</code> bis <code>Offset + 7</code>) in Netzwerk-Byte-Order (Big Endian) abgelegt wird, um Erkennung von Verwechslung und Falschadressierung im Profile 4m zu gewährleisten. Implementierungen müssen exakt diese Byte-Reihenfolge und Adressierung einhalten.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-6a5c35fb93aea222", "to": "FIG-562203aebc80c395", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
